    # recolor the zero gaps along those frame lines.
    row_zero_counts = [sum(v == 0 for v in row) for row in grid]
    col_zero_counts = [sum(grid[r][c] == 0 for r in range(h)) for c in range(w)]

    # Keep lines with several separated gaps, rather than ordinary isolated
    # background zeros.
    frame_rows = {r for r, n in enumerate(row_zero_counts) if n >= 4}
    frame_cols = {c for c, n in enumerate(col_zero_counts) if n >= 3}

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r in frame_rows or c in frame_cols):
